bool b = false;
std::cout &lt;&lt; &quot;b = &quot; &lt;&lt; b &lt;&lt; std::endl;
std::cout &lt;&lt; &quot;sizeof(bool) = &quot; &lt;&lt; sizeof(bool) &lt;&lt; std::endl;
