CPP/数组.content:
一维数组
定义

数组中的每个元素都是相同的数据类型
数组中的元素在内存空间中是连续的, 是顺序存储类型

int a[5];
for (int i = 0; i &lt; 5; i++) {
	a[i] = i + 1;  // 数组元素是从0开始索引的
}
int b[5] = {6, 7, 8, 9, 10};
int c[] = {11, 12, 13, 14, 15};
std::cout &lt;&lt; &quot;a[0] = &quot; &lt;&lt; a[0] &lt;&lt; std::endl;
std::cout &lt;&lt; &quot;b[0] = &quot; &lt;&lt; b[0] &lt;&lt; std::endl;
std::cout &lt;&lt; &quot;c[0] = &quot; &lt;&lt; c[0] &lt;&lt; std::endl;
$&gt; g++ ./definition.cpp -o definition
$&gt; ./definition
a[0] = 1
b[0] = 6
c[0] = 11
$&gt; 
数组名的作用

可以统计数组的长度
可以获取数组在内存中的首地址

int arr[10];
for (int i = 0; i &lt; 10; i++) {
	arr[i] = i + 1;
}

std::cout &lt;&lt; &quot;sizeof(arr) = &quot; &lt;&lt; sizeof(arr) &lt;&lt; std::endl;
std::cout &lt;&lt; &quot;sizeof(arr[0]) = &quot; &lt;&lt; sizeof(arr[0]) &lt;&lt; std::endl;
std::cout &lt;&lt; &quot;sizeof(arr) / sizeof(arr[0]) = &quot;
		  &lt;&lt; sizeof(arr) / sizeof(arr[0]) &lt;&lt; std::endl;

std::cout &lt;&lt; &quot;首地址 = &quot; &lt;&lt; arr &lt;&lt; std::endl;
std::cout &lt;&lt; &quot;arr[0]的地址 = &quot; &lt;&lt; &amp;arr[0] &lt;&lt; std::endl;
std::cout &lt;&lt; &quot;arr[1]的地址 = &quot; &lt;&lt; &amp;arr[1] &lt;&lt; std::endl;
int * p = reinterpret_cast&lt;int *&gt;(
	reinterpret_cast&lt;char *&gt;(&amp;arr[0]) + sizeof(int)
); // C++ 的指针运算的+n会根据类型大小进行偏移,
   // 这里转成char*是因为char*是单字节的, 符合偏移4字节的演示
   // 这行代码等价于int * p = &amp;arr[0] + 1
std::cout &lt;&lt; &quot;*p = &quot; &lt;&lt; *p &lt;&lt; std::endl;
$&gt; g++ ./name.cpp -o name
$&gt; ./name
sizeof(arr) = 40
sizeof(arr[0]) = 4
sizeof(arr) / sizeof(arr[0]) = 10
首地址 = 0x73ba5ffb60  # 对于地址来说, 每次运行均是不同的
arr[0]的地址 = 0x73ba5ffb60  # 数组首地址等价于首个元素的地址
arr[1]的地址 = 0x73ba5ffb64  # 相邻两个元素的地址差值是元素类型的字节数
*p = 2  # 偏移4字节后刚好等于arr[1]
$&gt; 
